Feedback em tempo real enquanto digita — client component (mesmo sem estado PRÓPRIO aqui, já que recebe a senha como prop, o pai que guarda o estado; mas deixo explícito "use client" já que este é o tipo de componente que sempre vive dentro de um formulário controlado). Critérios de força: tamanho ≥8, maiúscula, número, caractere especial — 4 checks = 4 barras. Cor semântica gradual (vermelho→âmbar→verde), `role="progressbar"` com os valores certos pra acessibilidade, e não renderiza nada se a senha estiver vazia (evita mostrar "Fraca" antes do usuário digitar qualquer coisa):
<tool_call>
{"name": "write_file", "arguments": {"path": "components/PasswordStrengthMeter.tsx", "content": ""use client";

function scoreOf(password: string): number {
  let score = 0;
  if (password.length >= 8) score++;
  if (/[A-Z]/.test(password)) score++;
  if (/[0-9]/.test(password)) score++;
  if (/[^A-Za-z0-9]/.test(password)) score++;
  return score;
}

const LEVELS = [
  { label: "Fraca", className: "bg-rose-500" },
  { label: "Razoável", className: "bg-amber-500" },
  { label: "Boa", className: "bg-amber-500" },
  { label: "Forte", className: "bg-emerald-500" },
];

export default function PasswordStrengthMeter({ password }: { password: string }) {
  const score = scoreOf(password);
  const level = LEVELS[Math.max(0, score - 1)];

  if (!password) return null;

  return (
    <div className="space-y-1">
      <div className="flex gap-1" role="progressbar" aria-valuenow={score} aria-valuemin={0} aria-valuemax={4}>
        {LEVELS.map((_, i) => (
          <div
            key={i}
            className={`h-1.5 flex-1 rounded-full transition-colors duration-150 ${
              i < score ? level.className : "bg-zinc-200 dark:bg-zinc-800"
            }`}
          />
        ))}
      </div>
      <p className="text-xs text-zinc-500 dark:text-zinc-400">{level.label}</p>
    </div>
  );
}
"}}
