Atualiza a cada segundo — client component com `useInterval` via `setInterval` dentro de `useEffect`, cleanup obrigatório (senão o interval sobrevive à desmontagem). Detalhes que evitam bug sutil: calcular `remaining` a partir da DIFERENÇA entre a data alvo e `Date.now()` a cada tick (não decrementar um contador local — isso desincroniza se a aba ficar em background, já que `setInterval` não é garantido rodar pontualmente); `aria-live="off"` deliberado, porque um número mudando a cada segundo seria insuportável pra leitor de tela anunciar; e um estado "Encerrado" explícito quando o tempo acaba, em vez de mostrar "00:00:00" pra sempre ou (pior) números negativos:
<tool_call>
{"name": "write_file", "arguments": {"path": "components/CountdownTimer.tsx", "content": ""use client";

import { useEffect, useState } from "react";

function formatRemaining(ms: number): string {
  const totalSeconds = Math.max(0, Math.floor(ms / 1000));
  const hours = Math.floor(totalSeconds / 3600);
  const minutes = Math.floor((totalSeconds % 3600) / 60);
  const seconds = totalSeconds % 60;
  return [hours, minutes, seconds].map((n) => String(n).padStart(2, "0")).join(":");
}

export default function CountdownTimer({ targetDate }: { targetDate: string }) {
  const [remaining, setRemaining] = useState(() => new Date(targetDate).getTime() - Date.now());

  useEffect(() => {
    const interval = setInterval(() => {
      setRemaining(new Date(targetDate).getTime() - Date.now());
    }, 1000);
    return () => clearInterval(interval);
  }, [targetDate]);

  const ended = remaining <= 0;

  return (
    <span
      className="font-mono text-sm font-semibold tabular-nums"
      aria-live="off"
    >
      {ended ? "Encerrado" : formatRemaining(remaining)}
    </span>
  );
}
"}}
</tool_call>

Reflects external state (value/max as props), no internal state of its own — but marking it client since it's meant to update live alongside a controlled textarea's onChange, and a pure display component that re-renders every keystroke still counts as client-adjacent in this codebase's convention. Three tiers: normal (muted), near-limit (amber, last 20 chars — arbitrary but reasonable threshold), over-limit (rose, negative remaining count made visually obvious). `aria-live="polite"` so screen readers get the updated count without interrupting typing:
<tool_call>
{"name": "write_file", "arguments": {"path": "components/CharacterCounter.tsx", "content": ""use client";

type CharacterCounterProps = {
  value: string;
  max: number;
};

export default function CharacterCounter({ value, max }: CharacterCounterProps) {
  const remaining = max - value.length;
  const isOver = remaining < 0;
  const isNear = remaining >= 0 && remaining <= 20;

  return (
    <span
      className={
        isOver
          ? "text-xs font-medium text-rose-600 dark:text-rose-400"
          : isNear
            ? "text-xs font-medium text-amber-600 dark:text-amber-400"
            : "text-xs text-zinc-400 dark:text-zinc-500"
      }
      aria-live="polite"
    >
      {value.length}/{max}
    </span>
  );
}
"}}
</tool_call>

Clipboard + hover-reveal state — client component. Details: the copy button stays invisible (`opacity-0`) until the container is hovered (`group-hover`), so it doesn't clutter the block when not needed; `overflow-x-auto` on the `<pre>` so long lines scroll instead of breaking the layout; optional language label as a subtle header, only rendered if provided; feedback text reverts after 2s:
<tool_call>
{"name": "write_file", "arguments": {"path": "components/CopyableCodeBlock.tsx", "content": ""use client";

import { useState } from "react";

export default function CopyableCodeBlock({ code, language }: { code: string; language?: string }) {
  const [copied, setCopied] = useState(false);

  async function handleCopy() {
    await navigator.clipboard.writeText(code);
    setCopied(true);
    setTimeout(() => setCopied(false), 2000);
  }

  return (
    <div className="group relative overflow-hidden rounded-xl border border-zinc-200 bg-zinc-50 dark:border-zinc-800 dark:bg-zinc-900">
      {language ? (
        <div className="border-b border-zinc-200 px-4 py-1.5 text-xs text-zinc-500 dark:border-zinc-800 dark:text-zinc-400">
          {language}
        </div>
      ) : null}
      <pre className="overflow-x-auto p-4 text-sm">
        <code>{code}</code>
      </pre>
      <button
        type="button"
        onClick={handleCopy}
        aria-label="Copy code"
        className="absolute right-2 top-2 rounded-lg border border-zinc-300 bg-white px-2 py-1 text-xs font-medium opacity-0 transition-opacity group-hover:opacity-100 dark:border-zinc-700 dark:bg-zinc-950"
      >
        {copied ? "Copied!" : "Copy"}
      </button>
    </div>
  );
}
"}}
</tool_call>

