Five fixes to actually communicate direction:
1. the core ask: semantic color — emerald for positive, rose for negative, neutral gray for exactly zero (a real case worth handling, not just positive/negative);
2. a directional arrow icon (▲/▼) reinforces color for colorblind users — never rely on color alone for meaning;
3. explicit `+` sign on positive values (bare "5%" doesn't read as clearly positive as "+5%" does);
4. `.toFixed(1)` for consistent decimal display instead of raw float inconsistency;
5. arrow marked `aria-hidden` since the sign and color already carry the meaning in text.
Writing it:
<tool_call>
{"name": "write_file", "arguments": {"path": "components/MetricDelta.tsx", "content": "export default function MetricDelta({ value }: { value: number }) {
  const isPositive = value > 0;
  const isNeutral = value === 0;
  const sign = isPositive ? "+" : "";

  return (
    <span
      className={
        isNeutral
          ? "inline-flex items-center gap-0.5 text-sm font-medium text-zinc-500 dark:text-zinc-400"
          : isPositive
            ? "inline-flex items-center gap-0.5 text-sm font-medium text-emerald-600 dark:text-emerald-400"
            : "inline-flex items-center gap-0.5 text-sm font-medium text-rose-600 dark:text-rose-400"
      }
    >
      {!isNeutral ? <span aria-hidden="true">{isPositive ? "▲" : "▼"}</span> : null}
      {sign}{value.toFixed(1)}%
    </span>
  );
}
"}}
</tool_call>

